def transform(grid):
    h, w = len(grid), len(grid[0])
    # Full monochrome non-background rows and columns are the separators.
    rows = [r for r in range(h) if grid[r][0] != 0 and all(v == grid[r][0] for v in grid[r])]
    cols = [c for c in range(w) if grid[0][c] != 0 and all(grid[r][c] == grid[0][c] for r in range(h))]
    out = [row[:] for row in grid]
    for r in rows:
        out[r] = [2] * w
    for c in cols:
        for r in range(h):
            out[r][c] = 2
    return out
